import { test, expect, Browser, BrowserContext, Page } from '@playwright/test';
import { createTestAccount, setupMockWallet, loginViaWallet } from '../utils/wallet-login-helpers';
import { createTestTextFile, cleanupTestFiles } from '../utils/test-files';
import { deleteAccountViaPage } from '../utils/cleanup-helpers';
import { FileListPage } from '../page-objects/file-browser/file-list.page';
import { UploadZonePage } from '../page-objects/file-browser/upload-zone.page';
import { SelectionActionBarPage } from '../page-objects/file-browser/selection-action-bar.page';
import { ContextMenuPage } from '../page-objects/file-browser/context-menu.page';

test.describe.serial('Batch Download', () => {
  let browser: Browser;
  let context: BrowserContext;
  let page: Page;
  let fileList: FileListPage;
  let uploadZone: UploadZonePage;
  let selectionBar: SelectionActionBarPage;
  let contextMenu: ContextMenuPage;
  const timestamp = Date.now();

  // Create 3 uniquely named test files
  const file1Name = `batch-dl-1-${timestamp}.txt`;
  const file2Name = `batch-dl-2-${timestamp}.txt`;
  const file3Name = `batch-dl-3-${timestamp}.txt`;

  test.beforeAll(async ({ browser: b }) => {
    browser = b;
    const account = createTestAccount();
    context = await browser.newContext();
    page = await context.newPage();
    await setupMockWallet(page, account);
    const result = await loginViaWallet(page, { timeout: 90_000 });
    expect(result.outcome).toBe('success');
    fileList = new FileListPage(page);
    uploadZone = new UploadZonePage(page);
    selectionBar = new SelectionActionBarPage(page);
    contextMenu = new ContextMenuPage(page);
  });

  test.afterAll(async () => {
    cleanupTestFiles();
    await deleteAccountViaPage(page);
    if (context) await context.close();
  });

  // ... tests below
});
```

Tests (5 total):

1. **'upload test files for batch operations'**
   - Create 3 text files: `createTestTextFile(file1Name, 'Batch download test file 1')`, same for 2 and 3.
   - Upload each via `uploadZone.uploadFile(file.path)`. After each upload, wait for upload complete: `uploadZone.waitForUploadComplete({ timeout: 30_000 })` and item appearance: `fileList.waitForItemToAppear(fileName, { timeout: 30_000 })`.
   - Assert all 3 files visible in list.

2. **'multi-select files shows selection action bar'**
   - Select first file: `fileList.selectItem(file1Name)`.
   - Ctrl+click second: `fileList.ctrlClickItem(file2Name)`.
   - Wait for selection bar: `selectionBar.waitForVisible({ timeout: 5_000 })`.
   - Assert count text contains "2": `expect(await selectionBar.getCountText()).toContain('2')`.
   - Assert download button is visible: `expect(await selectionBar.isDownloadVisible()).toBe(true)`.
   - Click somewhere to deselect (e.g., `page.locator('.file-list-header').click()` or use clear button).

3. **'batch download via selection bar triggers file download'**
   - Select file1 and file2 via selectItem + ctrlClickItem.
   - Wait for selection bar visible.
   - Set up download listener BEFORE clicking download: `const downloadPromise = page.waitForEvent('download', { timeout: 30_000 })`.
   - Click download: `selectionBar.clickDownload()`.
   - Await download event: `const download = await downloadPromise`.
   - Assert download has a suggested filename: `expect(download.suggestedFilename()).toBeTruthy()`.
   - Note: Only asserting first download event. Batch download fires multiple events sequentially but we only need to verify at least one succeeds.

4. **'select three files shows correct count'**
   - Select all 3 files: selectItem(file1) + ctrlClickItem(file2) + ctrlClickItem(file3).
   - Assert selection count: `expect(await fileList.getSelectedCount()).toBe(3)`.
   - Assert selection bar count text contains "3": `expect(await selectionBar.getCountText()).toContain('3')`.

5. **'batch context menu shows download option'**
   - With 3 files selected, right-click one of them: `fileList.rightClickItem(file2Name)`.
   - Wait for context menu: `contextMenu.waitForOpen()`.
   - Assert batch menu: `expect(await contextMenu.isBatchMenu()).toBe(true)`.
   - Assert header contains "selected": `expect(await contextMenu.getHeaderText()).toContain('selected')`.
   - Close menu: `contextMenu.closeWithEscape()`.

Add `test.setTimeout(120_000)` at top level (2 min -- uploads + downloads may be slow).
