import { describe, it, expect } from 'vitest';

describe('Throttle Bypass Diagnostic', () => {
  it('env vars are visible in vitest worker', () => {
    console.log('THROTTLE_BYPASS_SECRET:', process.env.THROTTLE_BYPASS_SECRET ?? '(empty)');
