    const SECRET = process.env.LOAD_TEST_SECRET!;
    const BYPASS = process.env.THROTTLE_BYPASS_SECRET!;

    const promises = Array.from({ length: 50 }, (_, i) =>
      fetch(`${API_URL}/auth/test-login`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Throttle-Bypass': BYPASS,
