        body: JSON.stringify({
          email: `diag-vitest-${i}-${Date.now()}@example.com`,
          secret: SECRET,
        }),
      }).then(async (r) => ({ i, status: r.status }))
        .catch((e) => ({ i, status: -1, error: (e as Error).message })),
    );

    const results = await Promise.all(promises);
    const ok = results.filter((r) => r.status === 200).length;
    const throttled = results.filter((r) => r.status === 429).length;
    const errors = results.filter((r) => r.status === -1).length;

    console.log(`Results: 200=${ok}, 429=${throttled}, errors=${errors}`);
    if (throttled > 0 || errors > 0) {
      const failures = results.filter((r) => r.status !== 200);
      console.log('Failures:', JSON.stringify(failures.slice(0, 3)));
    }

    expect(ok).toBe(50);
  }, 30_000);
});

