/**
 * Diagnostic: verify throttle bypass works through the actual createClientPool path.
 *
 * Run: set -a && source .env && set +a && npx vitest run src/scenarios/_diagnostic-throttle.test.ts
 */
import { describe, it, expect, afterAll } from 'vitest';
import { createClientPool, destroyClientPool, type PoolClient } from '../harness/client-pool';

describe('Throttle Bypass Diagnostic', () => {
  let pool: PoolClient[] = [];

  afterAll(async () => {
    if (pool.length > 0) await destroyClientPool(pool);
  });

  it('createClientPool creates 50 clients without 429', async () => {
    console.log('THROTTLE_BYPASS_SECRET:', process.env.THROTTLE_BYPASS_SECRET ? '(set)' : '(empty)');
    console.log('LOAD_TEST_API_URL:', process.env.LOAD_TEST_API_URL);

    pool = await createClientPool({ clientCount: 20, label: 'diag' });

    console.log(`Created ${pool.length}/20 clients`);
    expect(pool.length).toBe(20);
  }, 120_000);
});

